+using System.Net;
+using Uinsure.Policies.Api.Tests.Builders;
+using Uinsure.Policies.Api.Tests.Support;
+using Xunit;
+
+namespace Uinsure.Policies.Api.Tests;
+
+// COULD-2, the E5 ClaimResponse is the claim this request recorded (findings A2/R3 and A2/S1). Whatever happens
+// to the policy after this request's save, the 201 answers with its own claim: not the policy's last claim
+// when another claim lands straight after it, and not a 500 when the policy can't be read again. The events
+// after the save are made by AfterSaveApiFactory at exactly that point.
+//   start 2026-10-17 ends 2027-10-16; UK today 2026-11-20.
+public sealed class ClaimResponseTests : IClassFixture<AfterSaveApiFactory>
+{
+    private static readonly DateOnly TodayStartEnd = new(2027, 10, 16);
+    private static readonly DateTimeOffset ClaimsNow = new(2026, 11, 20, 12, 0, 0, TimeSpan.Zero);
+
+    private readonly AfterSaveApiFactory _factory;
+
+    public ClaimResponseTests(AfterSaveApiFactory factory)
+    {
+        _factory = factory;
+        _factory.ResetClock();
+    }
+
+    // Ours is dated 2026-11-19; the other request's, which commits straight after ours, 2026-11-20. Both are
+    // stored, ours first, and the 201 is ours.
+    [Fact]
+    [Trait("Rule", "COULD-2")]
+    public async Task Claim_answers_with_its_own_claim_when_another_claim_lands_straight_after_it()
+    {
+        const string reference = "CLAIM-OWN-RACE";
+        var sold = new SellPolicyRequestBuilder(reference)
+            .WithStartDate(TestClock.Today).WithAmount(318.92m).WithPaymentMethod("DirectDebit").Build();
+        using var client = _factory.CreateClient();
+        await client.SellAndReadBack(sold, reference);
+        _factory.Clock.SetUtcNow(ClaimsNow);
+        _factory.AnotherClaimAfterTheNextSaveOf(reference, new DateOnly(2026, 11, 20), "Fallen tree through the conservatory roof");
+
+        var body = await client.RecordClaim(
+            reference, new ClaimRequestBuilder().WithClaimDate(new DateOnly(2026, 11, 19)).WithDescription("Burst pipe under the kitchen sink").Build());
+
+        var claimReference = ClaimAssert.IsClaim(body, reference, new DateOnly(2026, 11, 19), "Burst pipe under the kitchen sink");
+        var policy = await client.ReadBack(reference);
+        var otherReference = policy.Member("claims")[1].Member("reference").GetString();
+        Assert.False(string.IsNullOrWhiteSpace(otherReference));
+        Assert.NotEqual(claimReference, otherReference);
+        PolicyStateAssert.ReadsBack(
+            policy, sold, reference, TodayStartEnd, "Active", true, null, [],
+            [
+                new ExpectedClaim(claimReference, new DateOnly(2026, 11, 19), "Burst pipe under the kitchen sink"),
+                new ExpectedClaim(otherReference, new DateOnly(2026, 11, 20), "Fallen tree through the conservatory roof"),
+            ]);
+    }
+
+    // The claim is saved, then the policy can no longer be found in this request: the 201 still answers with
+    // the claim recorded, never a 500, and the read-back that follows lists it.
+    [Fact]
+    [Trait("Rule", "COULD-2")]
+    public async Task Claim_answers_with_its_own_claim_when_the_policy_cannot_be_read_again_after_the_save()
+    {
+        const string reference = "CLAIM-OWN-NO-READ";
+        var sold = new SellPolicyRequestBuilder(reference)
+            .WithStartDate(TestClock.Today).WithAmount(447.06m).WithPaymentMethod("Card").Build();
+        using var client = _factory.CreateClient();
+        await client.SellAndReadBack(sold, reference);
+        _factory.Clock.SetUtcNow(ClaimsNow);
+        _factory.NothingFoundAfterTheNextSaveOf(reference);
+
+        using var response = await client.PostClaim(
+            reference, new ClaimRequestBuilder().WithClaimDate(new DateOnly(2026, 11, 18)).WithDescription("Kitchen window smashed by a ball").Build());
+
+        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
+        var claimReference = ClaimAssert.IsClaim(
+            await PolicyActions.ClaimedBody(response, reference), reference, new DateOnly(2026, 11, 18), "Kitchen window smashed by a ball");
+        PolicyStateAssert.ReadsBack(
+            await client.ReadBack(reference), sold, reference, TodayStartEnd, "Active", true, null, [],
+            [new ExpectedClaim(claimReference, new DateOnly(2026, 11, 18), "Kitchen window smashed by a ball")]);
+    }
+}
diff --git a/tests/Uinsure.Policies.Api.Tests/Support/AfterSaveApiFactory.cs b/tests/Uinsure.Policies.Api.Tests/Support/AfterSaveApiFactory.cs
new file mode 100644
index 0000000..daebfbd
--- /dev/null
+++ b/tests/Uinsure.Policies.Api.Tests/Support/AfterSaveApiFactory.cs
@@ -0,0 +1,99 @@
+using System.Collections.Concurrent;
+using Microsoft.AspNetCore.Hosting;
+using Microsoft.AspNetCore.TestHost;
+using Microsoft.Extensions.DependencyInjection;
+using Uinsure.Policies.Domain.Policies;
+using Uinsure.Policies.Services;
+
+namespace Uinsure.Policies.Api.Tests.Support;
+
+// The API with something happening to a policy straight after a request has saved it, through the real F3
+// endpoints. The app's IPolicyRepository is wrapped. A test arms a reference, and the next request that loaded
+// that policy and then saved it meets, once its own save has committed, one of:
+//   AnotherClaimAfterTheNextSaveOf: another request records a claim on the same policy, through the app's own
+//     IPolicyService in a scope of its own, as a concurrent claim committing just after this one would.
+//   NothingFoundAfterTheNextSaveOf: any later load of that policy in the same request finds nothing, as a read
+//     that fails would.
+// Each arming is used once, by the first request that saves the policy after it.
+public sealed class AfterSaveApiFactory : PoliciesApiFactory
+{
+    private readonly ConcurrentDictionary<string, OtherClaim> _otherClaims = new(StringComparer.Ordinal);
+    private readonly ConcurrentDictionary<string, bool> _unreadable = new(StringComparer.Ordinal);
+
+    public void AnotherClaimAfterTheNextSaveOf(string reference, DateOnly claimDate, string description) =>
+        _otherClaims[reference] = new OtherClaim(claimDate, description);
+
+    public void NothingFoundAfterTheNextSaveOf(string reference) => _unreadable[reference] = true;
+
+    protected override void ConfigureWebHost(IWebHostBuilder builder)
+    {
+        base.ConfigureWebHost(builder);
+
+        builder.ConfigureTestServices(services =>
+        {
+            var registered = services.Single(descriptor => descriptor.ServiceType == typeof(IPolicyRepository));
+            services.Remove(registered);
+            services.AddScoped<IPolicyRepository>(provider => new AfterSaveRepository(AppRepository(provider, registered), provider, this));
+        });
+    }
+
+    private static IPolicyRepository AppRepository(IServiceProvider provider, ServiceDescriptor registered) =>
+        registered.ImplementationFactory is not null
+            ? (IPolicyRepository)registered.ImplementationFactory(provider)
+            : (IPolicyRepository)ActivatorUtilities.CreateInstance(provider, registered.ImplementationType!);
+
+    // The other request: record its claim on the same policy, in a scope of its own, after this one's save.
+    private static async Task RecordFromAnotherRequest(IServiceProvider provider, PolicyReference reference, OtherClaim claim, CancellationToken ct)
+    {
+        using var other = provider.GetRequiredService<IServiceScopeFactory>().CreateScope();
+        var recorded = await other.ServiceProvider.GetRequiredService<IPolicyService>().RecordClaim(reference, claim.ClaimDate, claim.Description, ct);
+        if (!recorded.IsSuccess)
+        {
+            throw new InvalidOperationException($"The other request's claim on '{reference.Value}' was expected to be recorded.");
+        }
+    }
+
+    private sealed record OtherClaim(DateOnly ClaimDate, string Description);
+
+    private sealed class AfterSaveRepository(IPolicyRepository app, IServiceProvider provider, AfterSaveApiFactory factory) : IPolicyRepository
+    {
+        private readonly List<PolicyReference> _loaded = [];
+        private readonly HashSet<PolicyReference> _unreadable = [];
+
+        public async Task<Policy?> GetByReference(PolicyReference reference, CancellationToken ct)
+        {
+            if (_unreadable.Contains(reference))
+            {
+                return null;
+            }
+
+            var policy = await app.GetByReference(reference, ct);
+            if (policy is not null)
+            {
+                _loaded.Add(reference);
+            }
+
+            return policy;
+        }
+
+        public void Add(Policy policy) => app.Add(policy);
+
+        public async Task SaveChanges(CancellationToken ct)
+        {
+            await app.SaveChanges(ct);
+
+            foreach (var reference in _loaded.Distinct().ToArray())
+            {
+                if (factory._otherClaims.TryRemove(reference.Value, out var claim))
+                {
+                    await RecordFromAnotherRequest(provider, reference, claim, ct);
+                }
+
+                if (factory._unreadable.TryRemove(reference.Value, out _))
+                {
+                    _unreadable.Add(reference);
+                }
+            }
+        }
+    }
+}

